WITH cleaned AS (SELECT *, CASE WHEN device IN ('tablet', 'mobile') THEN 'Tier 1' ELSE 'Other' END device_group, COALESCE(browser, 'N/A') browser_filled FROM sessions WHERE browser IN ('Edge', 'Firefox') AND started_at > TIMESTAMP '2023-04-21 12:00:00') SELECT s.id, s.customer_id, s.browser, s.started_at, s.country, s.device_group, s.browser_filled, latest.web_event_event_type, latest.duration_sec FROM cleaned s JOIN LATERAL (SELECT c.event_type AS web_event_event_type, c.duration_sec FROM web_events c WHERE c.session_id = s.id ORDER BY c.event_time DESC, c.id DESC LIMIT 1) latest ON TRUE;
